import glob,os
names=['tomato_lower','tomato_try_grasp','recover_pose','open_air','tomato_pre','tomato_yaw_pre']
files=[]
for n in names:
 files=sorted(glob.glob(f'/app/output/calls/{n}/frames/over_shoulder_left_camera/*.jpg'))
 for f in files[::max(1,len(files)//5)]: files.append(f)
# fix collection
imgs=[]
for n in names:
 fs=sorted(glob.glob(f'/app/output/calls/{n}/frames/over_shoulder_left_camera/*.jpg'))
 take=fs if len(fs)<=4 else [fs[0],fs[len(fs)//3],fs[2*len(fs)//3],fs[-1]]
 for f in take:
  im=Image.open(f).resize((480,270)); imgs.append((n+'/'+os.path.basename(f),im))
w=960; h=((len(imgs)+1)//2)*300
out=Image.new('RGB',(w,h),'white');d=ImageDraw.Draw(out)
for i,(lab,im) in enumerate(imgs):
 x=(i%2)*480;y=(i//2)*300;out.paste(im,(x,y+20));d.text((x+5,y+3),lab,fill='black')
out.save('/app/output/captures/tomato_sequence.jpg')
PY"});
